WFJ.Data.add("spell", {
  [427020] = { "Aggiungi $N1 Lingotto di Rame per completare la spedizione.", nil, 0x470409ea, nil, "um" },
  [427065] = { "I tuoi critici in mischia ti rendono infuriato (attivando le abilità che richiedono di essere infuriato) e aumentano del $N1% i danni di ⟦Mortal Strike=Assalto Mortale⟧, Sete di Sangue e ⟦Shield Slam=Colpo di Scudo⟧ per $D1.", nil, 0xbe623cd5, nil, "um" },
  [427066] = { nil, "Infuriato. Danni di ⟦Mortal Strike=Assalto Mortale⟧, Sete di Sangue e ⟦Shield Slam=Colpo di Scudo⟧ aumentati del $N1%.", nil, 0xdbc6b713, "mu" },
  [427067] = { "Ottieni l'abilità Sapore del Sangue:\n\n$I1\nOgni volta che la tua abilità Squartamento infligge danni, la tua abilità Dominazione si attiva per $D1 o per $N2 attacco. Questo effetto non può verificarsi più di una volta ogni $D2.", nil, 0xce54e8fe, nil, "um" },
  [427068] = { "Ottieni l'abilità Vigilanza:\n\n$I1\nConcentra il tuo sguardo protettivo su un membro del gruppo o dell'incursione, riducendo del $N1% i danni che subisce e trasferendo a te il $N2% della minaccia che genera. Inoltre, ogni volta che viene colpito da un attacco, il tempo di recupero della tua Provocazione si azzera. Dura $D1. Questo effetto può essere attivo su un solo bersaglio alla volta.", nil, 0xcddfed5c, nil, "um" },
  [427069] = { "Ottieni l'abilità Maestria nello Scudo:\n\n$I1\nAumenta del $N1% tutti i danni fisici che infliggi mentre hai uno scudo equipaggiato e riduce del $N2% la durata di tutti gli effetti di disarmo usati contro di te. Non si cumula con altri effetti che riducono la durata del disarmo.", nil, 0xc6e53f92, nil, "um" },
  [427070] = { "Ottieni l'abilità Furia:\n\n$I1\nScateni la tua furia, aumentando del $N1% la tua potenza d'attacco per $D1. Questa abilità si può usare solo mentre sei infuriato.", nil, 0x5f89a2b1, nil, "um" },
  [427073] = { "Ottieni l'abilità Scudo e Spada:\n\n$I1\nQuando le tue abilità Sfondamento e Rivincita infliggono danni, hanno il $N1% di probabilità di azzerare il tempo di recupero della tua abilità Colpo di Scudo e di ridurne del $N2% il costo in rabbia per $D1.", nil, 0x9c4d9374, nil, "um" },
  [427074] = { "Ottieni l'abilità Collera Distruttiva:\n\n$I1\nI tuoi critici in mischia ti rendono infuriato (attivando le abilità che richiedono di essere infuriato) e aumentano del $N1% i danni di Assalto Mortale, Sete di Sangue e Colpo di Scudo per $D1.", nil, 0xa35782cc, nil, "um" },
  [427076] = { "Incidi sul tuo elmo la runa Sapore del Sangue:\n\n$I1\nOgni volta che la tua abilità Squartamento infligge danni, la tua abilità Dominazione si attiva per $D1 o per $N2 attacco. Questo effetto non può verificarsi più di una volta ogni $D2.", nil, 0x372b5a47, nil, "um" },
  [427078] = { "Incidi sul tuo elmo la runa Vigilanza:\n\n$I1\nConcentra il tuo sguardo protettivo su un membro del gruppo o dell'incursione, riducendo del $N1% i danni che subisce e trasferendo a te il $N2% della minaccia che genera. Inoltre, ogni volta che viene colpito da un attacco, il tempo di recupero della tua Provocazione si azzera. Dura $D1. Questo effetto può essere attivo su un solo bersaglio alla volta.", nil, 0x61f07c95, nil, "um" },
  [427080] = { "Incidi sul tuo elmo la runa Maestria nello Scudo:\n\n$I1\nAumenta del $N1% tutti i danni fisici che infliggi mentre hai uno scudo equipaggiato e riduce del $N2% la durata di tutti gli effetti di disarmo usati contro di te. Non si cumula con altri effetti che riducono la durata del disarmo.", nil, 0x9c5cde04, nil, "um" },
  [427081] = { "Incidi sui tuoi bracciali la runa Furia:\n\n$I1\nScateni la tua furia, aumentando del $N1% la tua potenza d'attacco per $D1. Questa abilità si può usare solo mentre sei infuriato.", nil, 0x0c6ff633, nil, "um" },
  [427082] = { "Incidi sui tuoi bracciali la runa Scudo e Spada:\n\n$I1\nQuando le tue abilità Sfondamento e Rivincita infliggono danni, hanno il $N1% di probabilità di azzerare il tempo di recupero della tua abilità Colpo di Scudo e di ridurne del $N2% il costo in rabbia per $D1.", nil, 0xa197703f, nil, "um" },
  [427084] = { "Incidi sui tuoi bracciali la runa Collera Distruttiva:\n\n$I1\nI tuoi critici in mischia ti rendono infuriato (attivando le abilità che richiedono di essere infuriato) e aumentano del $N1% i danni di Assalto Mortale, Sete di Sangue e Colpo di Scudo per $D1.", nil, 0x5e77eb3f, nil, "um" },
  [427086] = { nil, "Gli alleati entro $N1 m dalla Priestess of the Moon ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0xc3e84c43, "mu" },
  [427087] = { nil, "Gli alleati entro $N1 m dalla Priestess of the Moon ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0x36cb3ece, "mu" },
