  [427090] = { nil, "Gli alleati entro $N1 m dal Far Seer ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Blade Master vivo nel suo esercito.", nil, 0x4d4580bd, "mu" },
  [427091] = { nil, "Gli alleati entro $N1 m dal Far Seer ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Blade Master vivo nel suo esercito.", nil, 0x4d4580bd, "mu" },
  [427116] = { nil, "Gli alleati entro $N1 m dalla Priestess of the Moon ottengono il $N2% di salute in più e il $N3% di danni in più.\n\nQuesti valori aumentano per ogni Keeper of the Grove vivo nell'esercito della Priestess of the Moon, ognuno dei quali conferisce il $N4% di salute in più e il $N5% di danni in più.", nil, 0x4a3e5759, "mu" },
