  [427121] = { nil, "Gli alleati entro $N1 m dal Far Seer ottengono il $N2% di salute in più e il $N3% di danni in più.\n\nQuesti valori aumentano per ogni Blade Master vivo nell'esercito del Far Seer, ognuno dei quali conferisce il $N4% di salute in più e il $N5% di danni in più.", nil, 0x89fb86da, "mu" },
  [427123] = { nil, "Gli alleati entro $N1 m dalla Priestess of the Moon ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0x270bb4b9, "mu" },
  [427143] = { "Aumenta di $N1 tutti i danni subiti da un nemico per $D1.", "Tutti i danni subiti aumentati di $N1.", 0x32a4af77, 0xb418110c, "uu" },
  [427144] = { "Questo oggetto è intriso del potere grezzo del Vuoto. Quando chi lo porta viene attaccato, l'oggetto ha un'alta probabilità di infliggere una terribile maledizione, facendo subire all'attaccante danni aggiuntivi da tutte le fonti per $N1 s.", nil, 0x21583d70, nil, "um" },
  [427592] = { "Travestiti da membro della ⟦Scarlet Crusade=Crociata Scarlatta⟧. Le attività sospette faranno saltare il travestimento.", "Travestito da membro del ⟦Scarlet Monastery=Monastero Scarlatto⟧.", 0x6fd6b5d5, 0xcd5bf8dc, "uu" },
  [427625] = { nil, "Infligge $N1 danni da natura ogni $D1.", nil, 0x257a061c, "mu" },
  [427712] = { "Aumenta del $N1% il bonus ai danni critici di Corruzione, Bane of Agony, Anatema della Rovina, Risucchio d'Anima, ⟦Drain Life=Risucchio di Vita⟧, Aspirazione della Vita e Distruzione.", nil, 0x860f8d69, nil, "um" },
  [427713] = { "Conflagrazione fornisce anche il $N1% di celerità nel lancio degli incantesimi per $D1 e non consuma più Immolazione.", nil, 0x93b0d8a3, nil, "um" },
  [427714] = { nil, "Celerità nel lancio degli incantesimi aumentata del $N1%.", nil, 0x0f60ce95, "mu" },
  [427717] = { "L'energia d'ombra distrugge lentamente il bersaglio, infliggendo $N1 danni in $D1. Inoltre, se Afflizione Instabile viene dissolta, infligge $N3 danni a chi la dissolve e lo silenzia per $D2. Su un bersaglio può essere attiva una sola Afflizione Instabile o Immolazione per Stregone.", "$N1 danni da ombra ogni $D1. Se viene dissolto, infligge $N3 danni a chi lo dissolve e lo silenzia per $D2.", 0xaf411821, 0x88bbd8b6, "uu" },
  [427719] = { nil, "Silenziato.", nil, 0x20816e34, "mu" },
  [427726] = { "Brucia i nemici vicini infliggendo $N1 danni ogni volta che un nemico ti attacca in mischia (non più di una volta al secondo), riduce del $N2% tutti i danni magici subiti e aumenta del $N3% i danni da fuoco inflitti. Dura $D1.", "Bruci i nemici vicini infliggendo $N1 danni quando vieni attaccato, subisci il $N2% di danni magici in meno e infliggi il $N3% di danni da fuoco in più.", 0xfcb82619, 0x2cf4f599, "uu" },
  [427733] = { "Evoca una vilguardia al comando dello Stregone.\n\nLa vilguardia beneficia di tutti i talenti e gli effetti che si attivano dagli altri tuoi servitori demoniaci o che li potenziano.", nil, 0x81f505fa, nil, "um" },
  [427742] = { "Provoca la creatura, aumentando la probabilità che attacchi la vilguardia.", nil, 0xf8aa5bd9, nil, "um" },
  [427744] = { "Un attacco ad ampio raggio che infligge i danni dell'arma della vilguardia e $N1 danni aggiuntivi al bersaglio e al suo alleato più vicino.", nil, 0x1bb4f76b, nil, "um" },
  [427745] = { "Carica un nemico, infliggendo $N1 danni e stordendolo per $D1.", nil, 0x481312e4, nil, "um" },
  [427746] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [427751] = { nil, "Le acque purificatrici lavano via ogni impurità.", nil, 0x3316bbef, "mu" },
